PRAGMA defer_foreign_keys=ON;
CREATE TABLE channel_models_next (id TEXT PRIMARY KEY NOT NULL, channel_id TEXT NOT NULL, supplier_id TEXT NOT NULL, supplier_model_id TEXT NOT NULL, material_id TEXT NOT NULL, upstream_model_id TEXT NOT NULL, mapping_json TEXT NOT NULL CHECK(json_valid(mapping_json)), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), config_epoch INTEGER NOT NULL DEFAULT 1 CHECK(config_epoch>0), active_purchase_price_id TEXT, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, removed_at INTEGER, record_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(record_json)), UNIQUE(id,material_id,supplier_id), FOREIGN KEY(channel_id,supplier_id) REFERENCES channels(id,supplier_id), FOREIGN KEY(supplier_model_id,material_id,supplier_id) REFERENCES supplier_models(id,material_id,supplier_id), FOREIGN KEY(active_purchase_price_id,id) REFERENCES price_versions(id,channel_model_id));
INSERT INTO channel_models_next SELECT id,channel_id,supplier_id,supplier_model_id,material_id,upstream_model_id,mapping_json,enabled,config_epoch,active_purchase_price_id,revision,created_at,updated_at,removed_at,record_json FROM channel_models;
DROP TABLE channel_models;
ALTER TABLE channel_models_next RENAME TO channel_models;
CREATE INDEX mappings_material ON channel_models(material_id,removed_at,supplier_id,id);
CREATE INDEX mappings_supplier_model ON channel_models(supplier_model_id,removed_at);
CREATE UNIQUE INDEX mappings_active_source ON channel_models(channel_id,supplier_model_id,upstream_model_id) WHERE removed_at IS NULL;
DROP INDEX offers_provider;
DROP INDEX offers_call_current;
CREATE UNIQUE INDEX offers_call_current ON offers(id) WHERE retired_at IS NULL AND id<>'';
ALTER TABLE offers ADD COLUMN channel_model_id TEXT REFERENCES channel_models(id);
ALTER TABLE offers ADD COLUMN listing_stage TEXT NOT NULL DEFAULT 'unlisted' CHECK(listing_stage IN ('unlisted','gray','formal','withdrawn'));
ALTER TABLE offers ADD COLUMN gray_tenants_json TEXT NOT NULL DEFAULT '[]' CHECK(json_type(gray_tenants_json)='array');
UPDATE offers SET listing_stage=COALESCE((SELECT CASE s.listing_status WHEN 'listed' THEN CASE json_extract(s.record_json,'$.releaseStage') WHEN 'gray' THEN 'gray' ELSE 'formal' END WHEN 'withdrawn' THEN 'withdrawn' ELSE 'unlisted' END FROM services s WHERE s.id=offers.service_id),'unlisted'),gray_tenants_json=COALESCE((SELECT json_extract(s.record_json,'$.releaseTenantIds') FROM services s WHERE s.id=offers.service_id),'[]') WHERE retired_at IS NULL;
CREATE UNIQUE INDEX offers_provider ON offers(service_id,mode_epoch,COALESCE(channel_model_id,supplier_id)) WHERE mode='provider' AND retired_at IS NULL;
CREATE TABLE market_sessions (token_hash TEXT PRIMARY KEY NOT NULL, tenant_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE market_orders (id TEXT PRIMARY KEY NOT NULL, tenant_id TEXT NOT NULL, offer_id TEXT NOT NULL REFERENCES offers(record_id), sale_price_id TEXT NOT NULL REFERENCES price_versions(id), created_at INTEGER NOT NULL, UNIQUE(tenant_id,offer_id));
CREATE TABLE market_calls (tenant_id TEXT NOT NULL, request_id TEXT NOT NULL, request_hash TEXT NOT NULL, offer_id TEXT NOT NULL REFERENCES offers(record_id), sale_price_id TEXT NOT NULL REFERENCES price_versions(id), route_version_id TEXT NOT NULL REFERENCES route_versions(id), usage_id TEXT NOT NULL UNIQUE, response_json TEXT NOT NULL CHECK(json_valid(response_json)), created_at INTEGER NOT NULL, PRIMARY KEY(tenant_id,request_id));
CREATE TABLE market_migration_check (violations INTEGER CHECK(violations=0));
INSERT INTO market_migration_check SELECT COUNT(*) FROM pragma_foreign_key_check;
DROP TABLE market_migration_check;
PRAGMA defer_foreign_keys=OFF;
UPDATE db_state SET schema_version=11 WHERE id=1;
